P_CL1:      equ 36H     ; read ADRS / write CL1
P_CGC:      equ 37H     ; read: keyboard / write: CGC (b4 LCD clock CK0; 11H = PCTRL power-off step)
P_CPUSW:    equ 38H     ; CPU switch trigger (-> LH-5803)
P_IVEC:     equ 39H     ; IM2 vector low byte
P_SLOT:     equ 3CH     ; slot map (b6 LHS remap), mirror F08DH
