; ============================================================================
; RS-232C STATEMENTS AND FUNCTIONS
; All go through the COM IOCS (01D8H), channel in D:
;   01 set line parameters (FE22H baud word, FE24H format byte), 02 read them (DE ->)
;   0C PZONE, 0E/0F/16 break, 10 OUTSTAT, 11 INSTAT, 12 SETDEV, 13 status, 14 SNDSTAT,
;   15 RCVSTAT, 17/18 buffer / terminators (INIT), 1F.. PCONSOLE
; Format byte FE24H: b3-2 word length (5..8), b4 parity on, b5 even, b0 stop bits 2,
; b6 X-ON/X-OFF, b7 shift-in/out ("S"). SETCOM without parameters: 40H/00H/CCH
; (8 bits, no parity, 1 stop bit, X and S on).
; GETCOMDEV parses the device ("COM:"/"COM1:"/"COM2:") -> A.
; SETCOM dev[,baud][,len][,parity N|E|O][,stop 1|2][,X|N][,S|N]
; ============================================================================

;------------------------------------------------------------------------------
; 5382H - Basic command SETCOM
;------------------------------------------------------------------------------
K_SETCOM:
	call GETCOMDEV                  ; 5382  cded57
	jp c,NOTHERE                    ; 5385  da027d
	ld (0FE25H),a                   ; 5388  3225fe
	push hl                         ; 538B  e5
	ld c,02H                        ; 538C  0e02
