	defb 00H,00H,00H,00H,00H,00H,00H,00H; 7F33
	defb 00H,00H,00H,00H,00H,00H,00H,00H; 7F3B
	defb 00H,00H,00H,00H,00H,00H,00H,00H; 7F43
	defb 00H,00H,00H,00H,00H,00H,00H,00H; 7F4B
	defb 00H,00H,00H,00H,00H,00H,00H,00H; 7F53
	defb 00H,00H,00H,00H,00H        ; 7F5B
LOADTXTPATCH:
	ret c                           ; 7F60  d8
	ld de,0F31CH                    ; 7F61  111cf3
	ex de,hl                        ; 7F64  eb
	sbc hl,de                       ; 7F65  ed52
	ld a,70H                        ; 7F67  3e70
	ret c                           ; 7F69  d8
	ex de,hl                        ; 7F6A  eb
	ld a,1AH                        ; 7F6B  3e1a
	jp LOADTXTCH                    ; 7F6D  c3cf6f
LOADBINPATCH:
	ld a,(INBUF)                    ; 7F70  3a1df2
	bit 7,b                         ; 7F73  cb78
	jp z,LOADBINLN                  ; 7F75  ca936f
	ld a,70H                        ; 7F78  3e70
	scf                             ; 7F7A  37
	ret                             ; 7F7B  c9
	defb 00H,00H,00H,00H            ; 7F7C  00000000

; ----------------------------------------------------------------------------
; Gate area 7F80H..7FFCH. This block is byte-identical in B3 and B3b. Code in page 1
; that writes port 3DH switches the image under its own feet; the next instruction is
; fetched from the other image at the same address. Port 3DH b2 selects B3 (1) or B3b (0),
; b1 maps the JAPAN ROM (bank 4) into page 2.
;   7F80H..7F98H  JP table. The targets are addresses in B3 (they do not fit this image).
;   7F9BH..7FE0H  accessors that set 3DH := 02H (B3b + JAPAN ROM at 8000H) or the value
;                 in FDF6H, read words/blocks from 8000H.., and return through 7FF9H,
;                 which sets 3DH := 05H (B3 + b0).
; So a B3 routine that calls 7F9BH reads the JAPAN ROM with B3b mapped and gets back to
; B3. See the B3 notes.
; ----------------------------------------------------------------------------
L7F80:
	jp 756DH                        ; 7F80  c36d75
L7F83:
	jp 7570H                        ; 7F83  c37075
L7F86:
	jp 7580H                        ; 7F86  c38075
L7F89:
	jp 734DH                        ; 7F89  c34d73
L7F8C:
	jp 7369H                        ; 7F8C  c36973
L7F8F:
	jp 79F9H                        ; 7F8F  c3f979
L7F92:
	jp 73A8H                        ; 7F92  c3a873
L7F95:
	jp 7A70H                        ; 7F95  c3707a
L7F98:
	jp 7A7CH                        ; 7F98  c37c7a



;------------------------------------------------------------------------------
; 7F9BH - Read the word at 8000H of the JAPAN ROM -> DE
;------------------------------------------------------------------------------
JRDW8000:
	call SET3D02                    ; 7F9B  cdf17f
	ld de,(8000H)                   ; 7F9E  ed5b0080
	jr SET3D05                      ; 7FA2  1855



;------------------------------------------------------------------------------
; 7FA4H - Copy BC bytes from the JAPAN ROM, then 7 more after a skipped byte
;------------------------------------------------------------------------------
JRCOPY:
	call SET3D02                    ; 7FA4  cdf17f
	ldir                            ; 7FA7  edb0
	inc de                          ; 7FA9  13
	ld c,07H                        ; 7FAA  0e07
	ldir                            ; 7FAC  edb0
	jr SET3D05                      ; 7FAE  1849



;------------------------------------------------------------------------------
; 7FB0H - Copy BC bytes from the ROM selected by FDF6H
;------------------------------------------------------------------------------
JRCOPYX:
	ld a,(0FDF6H)                   ; 7FB0  3af6fd
	call SET3DA                     ; 7FB3  cdf37f
	ldir                            ; 7FB6  edb0
	jr SET3D05                      ; 7FB8  183f



;------------------------------------------------------------------------------
; 7FBAH - Read the ROM word at HL -> HL
;------------------------------------------------------------------------------
JRDWHL:
	call SET3D02                    ; 7FBA  cdf17f
	ld a,(hl)                       ; 7FBD  7e
	inc hl                          ; 7FBE  23
	ld h,(hl)                       ; 7FBF  66
	ld l,a                          ; 7FC0  6f
	jr SET3D05                      ; 7FC1  1836



;------------------------------------------------------------------------------
; 7FC3H - Read the ROM byte and word at HL -> C, DE
;------------------------------------------------------------------------------
JRDBDW:
	call SET3D02                    ; 7FC3  cdf17f
	ld c,(hl)                       ; 7FC6  4e
	inc hl                          ; 7FC7  23
	ld e,(hl)                       ; 7FC8  5e
	inc hl                          ; 7FC9  23
	ld d,(hl)                       ; 7FCA  56
	jr SET3D05                      ; 7FCB  182c



;------------------------------------------------------------------------------
; 7FCDH - Add B ROM bytes after HL to IX (carry into C)
;------------------------------------------------------------------------------
JRSUM:
	call SET3D02                    ; 7FCD  cdf17f
L7FD0:
	inc hl                          ; 7FD0  23
	ld e,(hl)                       ; 7FD1  5e
	add ix,de                       ; 7FD2  dd19
	jr nc,L7FD7                     ; 7FD4  3001
	inc c                           ; 7FD6  0c
L7FD7:
	djnz L7FD0                      ; 7FD7  10f7
	jr SET3D05                      ; 7FD9  181e



;------------------------------------------------------------------------------
; 7FDBH - Read the ROM byte at HL+1 (JAPAN ROM) -> A
;------------------------------------------------------------------------------
JRDBHL:
	call SET3D02                    ; 7FDB  cdf17f
	jr JRDBHL2                      ; 7FDE  1806



;------------------------------------------------------------------------------
; 7FE0H - Read the ROM byte at HL+1 (ROM selected by FDF6H) -> A
;------------------------------------------------------------------------------
JRDBHLX:
	ld a,(0FDF6H)                   ; 7FE0  3af6fd
	call SET3DA                     ; 7FE3  cdf37f
JRDBHL2:
	inc hl                          ; 7FE6  23
	ld d,(hl)                       ; 7FE7  56
	ld a,05H                        ; 7FE8  3e05
	ld (PORT3D_M),a                 ; 7FEA  327df0
	out (P_ROMSEL),a                ; 7FED  d33d
	ld a,d                          ; 7FEF  7a
	ret                             ; 7FF0  c9



;------------------------------------------------------------------------------
; 7FF1H - Select the JAPAN ROM (port 3DH := 02H)
;------------------------------------------------------------------------------
SET3D02:
	ld a,02H                        ; 7FF1  3e02



;------------------------------------------------------------------------------
; 7FF3H - Set port 3DH and its mirror := A
;------------------------------------------------------------------------------
SET3DA:
	ld (PORT3D_M),a                 ; 7FF3  327df0
	out (P_ROMSEL),a                ; 7FF6  d33d
	ret                             ; 7FF8  c9



;------------------------------------------------------------------------------
; 7FF9H - Back to the normal ROM selection (port 3DH := 05H)
;------------------------------------------------------------------------------
SET3D05:
	ld a,05H                        ; 7FF9  3e05
	jr SET3DA                       ; 7FFB  18f6
	defb 00H,00H,00H                ; 7FFD  000000

	end
